'use strict';
let currentView='console', hostChoice='', hostAvailable=true, reportAdded=false, reviewedCases=new Set(), activeLayer='all';
const tx=(en,es)=>lang==='es'?es:en;
const viewNames=()=>({map:tx('Neighborhood map','Mapa del vecindario'),refuge:tx('Explore a refuge','Explorar un refugio'),alerts:tx('When a route is uncertain','Cuando una ruta es incierta'),report:tx('Report flooding','Reportar inundación'),host:tx('Host dashboard','Panel de anfitrión'),console:tx('Coordinator console','Panel de coordinación'),care:tx('Care & essentials','Atención y recursos')});
function glyph(name){const d={map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',home:'M3 11l9-8 9 8 M5 10v11h14V10 M9 21v-7h6v7',report:'M4 6h4l2-3h4l2 3h4v15H4z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',alert:'M12 3 22 21H2z M12 9v5 M12 17v.1',console:'M3 3h18v18H3z M3 9h18 M9 9v12',care:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6z',arrow:'M4 12h16 M14 6l6 6-6 6',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 8 0 0 1 16 0v3',check:'M5 12l4 4L19 6'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${d[name]||d.map}"/></svg>`}
const demoPill=()=>`<span class="demo-pill">${tx('DEMO SCENARIO','ESCENARIO DEMO')}</span>`;
function go(view){currentView=view;render();document.querySelector('#view-title')?.focus();window.scrollTo({top:0,behavior:'instant'});}
function mapGraphic(route=false,small=false){const markers=[[178,105],[523,126],[580,330],[223,346],[91,240]];return `<div class="map-art ${small?'map-small':''}"><svg viewBox="0 0 700 450" role="img" aria-label="${tx('Illustrative neighborhood map. Fictional flood area, host locations and crossings. Not for navigation.','Mapa ilustrativo. Área inundada, anfitriones y cruces ficticios. No usar para navegar.')}"><defs><pattern id="blocks-${route}-${small}" width="145" height="105" patternUnits="userSpaceOnUse"><rect width="145" height="105" fill="#e9eeec"/><rect x="11" y="11" width="123" height="83" rx="5" fill="#dfe5e2"/><path d="M0 0H145M0 0V105" stroke="#fff" stroke-width="12"/></pattern></defs><rect width="700" height="450" fill="url(#blocks-${route}-${small})"/><g fill="#d5e3d4"><rect x="18" y="326" width="112" height="98" rx="20"/><rect x="584" y="17" width="100" height="75" rx="16"/><rect x="313" y="125" width="100" height="65" rx="12"/></g><path d="M-20 98C120 95 180 164 280 225S460 265 530 345 630 430 730 405" stroke="#b9d1ed" stroke-width="79" fill="none" opacity=".7"/><path d="M-20 98C120 95 180 164 280 225S460 265 530 345 630 430 730 405" stroke="#8fb3db" stroke-width="27" fill="none"/><path d="M-20 98C120 95 180 164 280 225S460 265 530 345 630 430 730 405" stroke="#c8dff7" stroke-width="10" fill="none"/><path d="M-5 294H705" stroke="#fff" stroke-width="22"/><path d="M-5 294H705" stroke="#f0d797" stroke-width="9"/><path d="M448-10V460" stroke="#fff" stroke-width="18"/><path d="M448-10V460" stroke="#cad1d3" stroke-width="5"/><g font-family="system-ui" font-size="11" fill="#607579"><text x="55" y="282">LOOP 410 · ${tx('ILLUSTRATION','ILUSTRACIÓN')}</text><text x="457" y="61">PERRIN BEITEL RD</text><text x="310" y="373" transform="rotate(25 310 373)">BEITEL CREEK</text><text x="36" y="383">${tx('Neighborhood park','Parque')}</text></g>${activeLayer!=='hosts'?`<g fill="#ac5838" stroke="#fff" stroke-width="3"><circle cx="274" cy="222" r="13"/><circle cx="448" cy="291" r="13"/></g><g fill="#fff" font-size="18" font-family="system-ui" text-anchor="middle"><text x="274" y="228">×</text><text x="448" y="297">×</text></g>`:''}${activeLayer!=='flood'?markers.map(([x,y],i)=>`<g><circle cx="${x}" cy="${y}" r="17" fill="#fff"/><circle cx="${x}" cy="${y}" r="12" fill="#39746b"/><path d="M${x-5} ${y}l5-5 5 5v5h-10z" fill="white"/></g>`).join(''):''}${route?'<path d="M354 121H178V105" stroke="white" stroke-width="10" fill="none"/><path d="M354 121H178V105" stroke="#39746b" stroke-width="5" stroke-dasharray="7 6" fill="none"/>':''}<circle cx="354" cy="121" r="25" fill="#729bc3" opacity=".2"/><circle cx="354" cy="121" r="10" fill="#285e9a" stroke="white" stroke-width="4"/><rect x="287" y="151" width="135" height="28" rx="14" fill="white"/><text x="354" y="169" font-family="system-ui" font-size="10" fill="#233b50" text-anchor="middle">${tx('Sample resident location','Ubicación de ejemplo')}</text></svg><span class="map-watermark">${tx('ILLUSTRATION · NOT FOR NAVIGATION','ILUSTRACIÓN · NO USAR PARA NAVEGAR')}</span></div>`}
function mapLegend(){return `<div class="map-legend"><span><i class="legend-flood"></i>${tx('Flood scenario','Inundación ficticia')}</span><span><i class="legend-closed">×</i>${tx('Sample closure','Cierre de ejemplo')}</span><span><i class="legend-host"></i>${tx('Sample host','Anfitrión ficticio')}</span><span><i class="legend-you"></i>${tx('Demo resident','Residente demo')}</span></div>`}
function warning(){return `<aside class="scenario-warning">${glyph('alert')}<div><strong>${tx('Flooding can change your next step.','Una inundación puede cambiar tu siguiente paso.')}</strong><p>${tx('Illustrative Beitel Creek scenario. Check official information before traveling.','Escenario ilustrativo de Beitel Creek. Consulta información oficial antes de viajar.')}</p></div><button data-action="updates">${tx('Official sources','Fuentes oficiales')} ↗</button></aside>`}
function heading(kicker,title,description){return `<div class="view-heading"><div><p class="kicker">${kicker}</p><h1 id="view-title" tabindex="-1">${title}</h1><p>${description}</p></div>${demoPill()}</div>`}
function mapView(){return `${heading(tx('YOUR COMMUNITY, CONNECTED','TU COMUNIDAD, CONECTADA'),tx('A clearer path to support.','Un camino más claro hacia el apoyo.'),tx('Explore the neighborhood. Understand your options. Take the next step.','Explora el vecindario. Conoce tus opciones. Da el siguiente paso.'))}${warning()}<div class="resident-grid"><section class="panel map-panel"><div class="panel-heading"><div><h2>${tx('Neighborhood overview','Vista del vecindario')}</h2><p>San Antonio · Bexar County</p></div><span class="subtle-tag">${tx('Sample map','Mapa de ejemplo')}</span></div><div class="map-filters" aria-label="${tx('Map layers','Capas del mapa')}">${[['all',tx('All layers','Todas')],['flood',tx('Flood scenario','Inundación')],['hosts',tx('Sample hosts','Anfitriones')]].map(([v,l])=>`<button data-layer="${v}" aria-pressed="${activeLayer===v}">${l}</button>`).join('')}</div>${mapGraphic()}${mapLegend()}<div class="map-bottom">${glyph('alert')}<p>${tx('No live location, flood alerts, or route verification. This map is a visual demonstration.','Sin ubicación en vivo, alertas reales ni verificación de rutas. Este mapa es una demostración visual.')}</p></div></section><aside class="map-sidebar"><section class="panel refuge-prompt"><span class="square-icon">${glyph('home')}</span><p class="kicker">${tx('A PLACE TO PAUSE','UN LUGAR PARA DESCANSAR')}</p><h2>${tx('Support starts <br>with a place to go.','El apoyo comienza <br>con un lugar adonde ir.')}</h2><p>${tx('See how a resident could explore nearby refuge and accommodation needs.','Explora cómo un residente podría buscar refugio y alojamiento cercano.')}</p><div class="host-mini"><span class="avatar">MG</span><span><strong>${tx('Meet a sample host','Conoce un anfitrión de ejemplo')}</strong><small>${tx('Fictional profile · No availability verified','Perfil ficticio · Sin disponibilidad verificada')}</small></span></div><button class="primary wide" data-view="refuge">${tx('Explore a refuge','Explorar un refugio')} ${glyph('arrow')}</button><button class="outline wide" data-view="alerts">${tx('What if a route is uncertain?','¿Y si la ruta es incierta?')}</button></section><section class="panel compact-panel"><span class="square-icon pale">${glyph('care')}</span><div><h3>${tx('Care comes with you.','Tu atención también importa.')}</h3><p>${tx('Medication, medical care, and essential support.','Medicamentos, atención médica y apoyo esencial.')}</p><button class="inline-link" data-view="care">${tx('Explore care resources','Explorar recursos de atención')} →</button></div></section></aside></div><section class="quick-actions"><button data-view="report">${glyph('report')}<span><strong>${tx('Report a concern','Reportar un problema')}</strong><small>${tx('Try a local-only flood report','Prueba un reporte local')}</small></span><b>↗</b></button><button data-view="host">${glyph('home')}<span><strong>${tx('Open your door','Abre tu puerta')}</strong><small>${tx('Explore the host experience','Explora la experiencia de anfitrión')}</small></span><b>↗</b></button><button data-action="emergency">${glyph('alert')}<span><strong>${tx('Need emergency help?','¿Necesitas ayuda de emergencia?')}</strong><small>${tx('Call 911 in immediate danger','Llama al 911 en peligro inmediato')}</small></span><b>↗</b></button></section>`}
function refugeView(){return `${heading(tx('RESIDENT EXPERIENCE','EXPERIENCIA DEL RESIDENTE'),tx('A possible place to stay.','Un posible lugar donde quedarse.'),tx('A fictional match to demonstrate the experience—not a reservation.','Una coincidencia ficticia para mostrar la experiencia; no es una reserva.'))}<div class="detail-grid"><section class="panel"><div class="panel-heading"><h2>${tx('Illustrative connection','Conexión ilustrativa')}</h2><span class="subtle-tag">${tx('Not directions','No son indicaciones')}</span></div>${mapGraphic(true)}<div class="map-bottom">${glyph('alert')}<p>${tx('The dotted line is a design example, not a walking route. No travel time or route safety has been established.','La línea punteada es un ejemplo de diseño, no una ruta a pie. No se ha establecido tiempo de viaje ni seguridad.')}</p></div></section><section class="panel profile"><div class="profile-title"><span class="avatar big">MG</span><div><h2>Maria G.</h2><p>${tx('Fictional host profile','Perfil de anfitriona ficticio')}</p></div></div><div class="feature-tags"><span>${tx('Space for 4','Espacio para 4')}</span><span>${tx('Pets welcome','Mascotas bienvenidas')}</span><span>Habla español</span><span>${tx('Second floor','Segundo piso')}</span></div><h3>${tx('Details to confirm first','Detalles que confirmar primero')}</h3><ul class="check-list"><li>${tx('Host identity and current availability','Identidad y disponibilidad actual')}</li><li>${tx('Accessibility and household needs','Accesibilidad y necesidades del hogar')}</li><li>${tx('Official travel and evacuation instructions','Instrucciones oficiales de viaje y evacuación')}</li></ul><p class="note">${tx('No host has been contacted. No address or personal contact details are shared in this demo.','No se ha contactado a ningún anfitrión. Esta demo no comparte direcciones ni datos de contacto personales.')}</p><button class="primary wide" data-sim="refuge">${tx('Preview a demo request','Ver una solicitud de demo')}</button><a class="outline wide button" href="https://www.211texas.org/">${tx('Find real resources at 2-1-1 Texas','Recursos reales en 2-1-1 Texas')} ↗</a></section></div>`}
function alertsView(){return `${heading(tx('RESIDENT GUIDANCE','ORIENTACIÓN PARA RESIDENTES'),tx('Uncertain conditions. Clear priorities.','Condiciones inciertas. Prioridades claras.'),tx('This screen cannot determine whether to evacuate or stay where you are.','Esta pantalla no puede determinar si debes evacuar o permanecer donde estás.'))}<div class="detail-grid"><section class="dark-panel"><span class="square-icon">${glyph('alert')}</span><p class="kicker">${tx('NO ROUTE VERIFIED','NINGUNA RUTA VERIFICADA')}</p><h2>${tx('Do not rely on this demo<br>to choose a safe route.','No uses esta demo<br>para elegir una ruta segura.')}</h2><p>${tx('Follow instructions from local emergency officials. In immediate danger, call 911.','Sigue las instrucciones de las autoridades locales. En peligro inmediato, llama al 911.')}</p><ol class="safety-steps"><li>${tx('Do not walk or drive through floodwater.','No camines ni conduzcas por agua de inundación.')}</li><li>${tx('Use official weather alerts and local emergency instructions.','Consulta alertas meteorológicas e instrucciones locales oficiales.')}</li><li>${tx('Do not wait for a message from this website. No responder monitors it.','No esperes un mensaje de este sitio. Ningún servicio de emergencia lo supervisa.')}</li></ol><a class="button emergency-wide" href="tel:911">${tx('Call 911','Llamar al 911')} ↗</a></section><section class="panel profile"><h2>${tx('Information you can act on','Información para decidir')}</h2><p>${tx('Use the official sources directly for current conditions and instructions.','Consulta las fuentes oficiales directamente para conocer condiciones e instrucciones actuales.')}</p><a class="resource-row" href="https://www.weather.gov/">National Weather Service <span>↗</span></a><a class="resource-row" href="https://www.weather.gov/safety/flood-during">${tx('Flood safety guidance','Seguridad ante inundaciones')} <span>↗</span></a><a class="resource-row" href="https://www.211texas.org/">2-1-1 Texas <span>↗</span></a><p class="note">${tx('This demo has not shared your location with a coordinator or family member. It cannot send text alerts.','Esta demo no ha compartido tu ubicación con coordinadores ni familiares. No envía alertas por mensaje.')}</p><button class="outline wide" data-view="map">${tx('Return to the map','Volver al mapa')}</button></section></div>`}
function reportView(){return `${heading(tx('COMMUNITY REPORTING','REPORTES COMUNITARIOS'),tx('Make a concern easier to understand.','Ayuda a entender un problema.'),tx('Try the reporting flow with a fictional example. No photo or location is collected.','Prueba el reporte con un ejemplo ficticio. No se recopilan fotos ni ubicación.'))}<div class="detail-grid"><section class="panel report-scene"><div class="scene-illustration"><svg viewBox="0 0 600 330" role="img" aria-label="${tx('Illustration of a flooded street, not an uploaded photo','Ilustración de una calle inundada; no es una foto subida')}"><rect width="600" height="330" fill="#d8e1e4"/><path d="M220 100L90 330H540L385 100Z" fill="#7c929b"/><path d="M0 100h180v110H0M430 60h170v150H430" fill="#9eafac"/><path d="M0 90l90-65 90 65M430 50l85-40 85 40" fill="#526667"/><path d="M0 235q130-40 270 0t330-10v105H0" fill="#97aeb9"/><path d="M0 267q130-40 270 0t330-10M0 303q130-40 270 0t330-10" stroke="#d0dde2" stroke-width="3" fill="none"/><path d="M240 200l25-48h83l30 48v45H240Z" fill="#354f60"/><path d="M272 160h68l18 33h-102z" fill="#b6ced5"/><path d="M215 244q80-20 180 0" stroke="#dce6e9" stroke-width="5" fill="none"/></svg><span>${tx('SAMPLE ILLUSTRATION · NOT A PHOTO','ILUSTRACIÓN DE EJEMPLO · NO ES FOTO')}</span></div><div class="profile"><h2>${tx('A road covered by water','Una calle cubierta de agua')}</h2><p>${tx('Fictional scene · No location attached','Escena ficticia · Sin ubicación adjunta')}</p><p class="note">${tx('Never enter floodwater to take a photo. For immediate danger, call 911 rather than using a report form.','Nunca entres al agua para tomar una foto. En peligro inmediato, llama al 911 en vez de usar un formulario.')}</p></div></section><section class="panel profile"><span class="subtle-tag">${tx('SIMULATED REVIEW · NOT AI ANALYSIS','REVISIÓN SIMULADA · NO ES ANÁLISIS DE IA')}</span><h2>${tx('What needs a human check?','¿Qué necesita revisión humana?')}</h2><div class="review-row"><span>${tx('Water on roadway','Agua sobre la calle')}</span><strong>${tx('Illustrated','Ilustrado')}</strong></div><div class="review-row"><span>${tx('Water depth & movement','Profundidad y movimiento')}</span><strong>${tx('Unknown','Desconocidos')}</strong></div><div class="review-row"><span>${tx('People in danger','Personas en peligro')}</span><strong>${tx('Not determined','Sin determinar')}</strong></div><p>${tx('A real report would need verification. This demo does not infer depth, close a road, or contact city staff.','Un reporte real requeriría verificación. Esta demo no estima profundidad, cierra calles ni contacta al personal municipal.')}</p><button class="primary wide" id="report-add" ${reportAdded?'disabled':''}>${reportAdded?tx('Demo report added locally','Reporte demo agregado localmente'):tx('Add sample to demo queue','Agregar ejemplo a la cola demo')}</button><p class="note" role="status">${reportAdded?tx('Saved in this page session only. Open the coordinator console to review it.','Guardado solo en esta sesión. Abre el panel de coordinación para revisarlo.'):tx('Nothing is sent. The example appears only in this session’s coordinator demo.','No se envía nada. El ejemplo aparece solo en el panel demo de esta sesión.')}</p><button class="inline-link" data-view="console">${tx('Open coordinator demo','Abrir panel de coordinación')} →</button></section></div>`}
function hostView(){return `${heading(tx('HOST EXPERIENCE','EXPERIENCIA DEL ANFITRIÓN'),tx('A little space. A meaningful difference.','Un poco de espacio. Una gran diferencia.'),tx('Explore a fictional hosting request and its review steps.','Explora una solicitud ficticia de alojamiento y sus pasos de revisión.'))}<div class="detail-grid"><section class="dark-panel"><p class="kicker">${tx('SAMPLE REQUEST · NOT A REAL FAMILY','SOLICITUD DE EJEMPLO · FAMILIA FICTICIA')}</p><h2>${tx('A family of 3<br>needs a place to pause.','Una familia de 3<br>necesita un lugar para descansar.')}</h2><p>${tx('Illustrative request · Nobody is traveling to you','Solicitud ilustrativa · Nadie se dirige hacia ti')}</p><div class="household"><div><strong>2</strong><span>${tx('Adults','Adultos')}</span></div><div><strong>1</strong><span>${tx('Child','Menor')}</span></div><div><strong>1</strong><span>${tx('Dog','Perro')}</span></div></div><p>${tx('Identity, accessibility needs, host suitability, and travel conditions would all need confirmation before a real placement.','La identidad, accesibilidad, idoneidad del alojamiento y condiciones de viaje deben confirmarse antes de un alojamiento real.')}</p><div class="host-actions"><button class="outline" data-host="declined" ${hostChoice?'disabled':''}>${tx('Decline demo','Rechazar demo')}</button><button class="teal-button" data-host="accepted" ${hostChoice||!hostAvailable?'disabled':''}>${tx('Accept demo request','Aceptar solicitud demo')}</button></div><p class="host-feedback" role="status">${hostChoice?tx(`Demo ${hostChoice}. No guest has been contacted.` ,hostChoice==='accepted'?'Demo aceptada. No se ha contactado a ningún huésped.':'Demo rechazada. No se ha contactado a ningún huésped.'):!hostAvailable?tx('Turn on demo availability to try accepting.','Activa disponibilidad demo para probar la aceptación.'):tx('This only changes your local demo state.','Esto solo cambia el estado local de la demo.')}</p></section><section class="panel profile"><div class="profile-title"><span class="avatar big">MG</span><div><h2>Maria G.</h2><p>${tx('Fictional host · Demo profile','Anfitriona ficticia · Perfil demo')}</p></div></div><label class="availability"><span>${tx('Available in this demo','Disponible en esta demo')}</span><input id="host-available" type="checkbox" role="switch" ${hostAvailable?'checked':''}></label><div class="review-row"><span>${tx('Space','Espacio')}</span><strong>${tx('Up to 4 · Pets welcome','Hasta 4 · Mascotas')}</strong></div><div class="review-row"><span>${tx('Identity verification','Verificación de identidad')}</span><strong>${tx('Not performed','No realizada')}</strong></div><div class="review-row"><span>${tx('Host safety review','Revisión del alojamiento')}</span><strong>${tx('Not performed','No realizada')}</strong></div><div class="note"><strong>${tx('No payment program connected','Sin programa de pagos conectado')}</strong><p>${tx('This prototype does not promise city payments or process compensation.','Este prototipo no promete pagos municipales ni procesa compensaciones.')}</p></div><button class="inline-link" data-view="console">${tx('See coordinator view','Ver panel de coordinación')} →</button></section></div>`}
function consoleView(){const rows=[['photo',tx('Photo report · Sample crossing','Reporte visual · Cruce ficticio'),tx('Water on roadway. Depth and people in danger need verification.','Agua sobre la calle. Profundidad y personas en peligro requieren verificación.')],['route',tx('Resident · Route uncertainty','Residente · Ruta incierta'),tx('No route has been verified. No responder has been assigned.','No hay ruta verificada. No se ha asignado ayuda.')],['match',tx('Host match · Household needs','Alojamiento · Necesidades del hogar'),tx('Accessibility, identity, and actual availability need confirmation.','Se deben confirmar accesibilidad, identidad y disponibilidad real.')],...(reportAdded?[['new-report',tx('New local sample report','Nuevo reporte local de ejemplo'),tx('Added from the report screen in this page session.','Agregado desde la pantalla de reportes en esta sesión.')]]:[])];return `${heading(tx('COORDINATION DEMO','DEMO DE COORDINACIÓN'),tx('See the situation. Keep people in the loop.','Comprende la situación. Mantén a las personas informadas.'),tx('Fictional operational view. No city systems or responders are connected.','Vista operativa ficticia. Sin conexión a sistemas municipales ni servicios de emergencia.'))}<div class="metrics"><div><span>${tx('Sample cases','Casos de ejemplo')}</span><strong>${rows.length}</strong></div><div><span>${tx('Awaiting demo review','Pendientes de revisión demo')}</span><strong>${rows.length-reviewedCases.size}</strong></div><div><span>${tx('Host demo decision','Decisión demo del anfitrión')}</span><strong class="metric-word">${hostChoice==='accepted'?tx('Accepted','Aceptada'):hostChoice==='declined'?tx('Declined','Rechazada'):tx('Pending','Pendiente')}</strong></div><div><span>${tx('Real requests sent','Solicitudes reales enviadas')}</span><strong>0</strong></div></div><div class="console-grid"><section class="panel"><div class="panel-heading"><h2>${tx('Scenario map','Mapa del escenario')}</h2>${demoPill()}</div>${mapGraphic(false,true)}${mapLegend()}</section><section class="panel queue"><div class="panel-heading"><h2>${tx('Needs a human','Necesita revisión humana')}</h2><span class="count">${rows.length-reviewedCases.size}</span></div><p class="queue-note">${tx('Simulate review. Nothing leaves this device.','Simula una revisión. Nada sale de este dispositivo.')}</p>${rows.map(([id,title,desc])=>`<article class="case"><span class="case-label">${reviewedCases.has(id)?tx('DEMO REVIEWED','DEMO REVISADA'):tx('REVIEW NEEDED','REVISIÓN NECESARIA')}</span><h3>${title}</h3><p>${desc}</p><button class="outline" data-review="${id}" ${reviewedCases.has(id)?'disabled':''}>${reviewedCases.has(id)?tx('Reviewed locally','Revisado localmente'):tx('Review demo case','Revisar caso demo')}</button></article>`).join('')}</section></div><p class="footnote">${tx('Reviewing a case does not approve a placement, close a road, or dispatch emergency services.','Revisar un caso no aprueba alojamiento, cierra calles ni envía servicios de emergencia.')}</p>`}
function careView(){const c=t();return `${heading(tx('CARE & ESSENTIALS','ATENCIÓN Y RECURSOS'),tx('Your care still matters.','Tu atención sigue siendo importante.'),tx('The original HighGround support flow, now part of the neighborhood experience.','El flujo original de apoyo de HighGround, ahora parte de la experiencia del vecindario.'))}<section class="care-area"><h2>${c.need}</h2><div class="cards">${c.services.map((s,i)=>`<button class="card" data-service="${i}" aria-pressed="${selected===i}"><span class="icon">${icon(['medical','pill','home','car'][i])}</span><strong>${s}</strong><span class="description">${c.descriptions[i]}</span></button>`).join('')}</div><p class="selection" id="selection" aria-live="polite">${selected<0?c.select:c.chosen+' '+c.services[selected]}</p><div class="cta"><button class="primary" data-action="request">${c.cta} ${glyph('arrow')}</button><p>${c.ctaNote}</p></div><section class="how"><h2>${c.how}</h2><div class="steps">${c.steps.map((s,i)=>`<div><span class="step-number">${i+1}</span><h3>${s}</h3><p>${c.stepDesc[i]}</p></div>`).join('')}</div></section></section>`}
function renderExperience(){if(currentView==='console'){renderCoordinator();return;}document.body.classList.remove('coordinator-mode');const c=t();document.documentElement.lang=lang;document.querySelector('.skip').textContent=tx('Skip to main content','Ir al contenido principal');document.querySelector('.close').setAttribute('aria-label',c.close);const names=viewNames();const nav=[['map','map',tx('Map','Mapa')],['report','report',tx('Report','Reportar')],['host','home',tx('Host','Anfitrión')],['alerts','alert',tx('Guidance','Orientación')],['care','care',tx('Care','Atención')]];document.querySelector('#app').innerHTML=`<div class="experience"><header class="app-header"><button class="brand" data-view="map" aria-label="HighGround — ${tx('map','mapa')}"><span class="brand-mark"><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M20 70L40 38 55 59 64 47 80 70Z" fill="white" stroke="none"/><path d="M17 79Q32 71 50 79T83 79" fill="none" stroke="#60a5fa" stroke-width="6" stroke-linecap="round"/></svg></span><span>HighGround<small>San Antonio · Bexar County</small></span></button><nav class="desktop-nav" aria-label="${tx('Main navigation','Navegación principal')}">${nav.map(([id,ic,label])=>`<button data-view="${id}" ${currentView===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="header-tools"><button id="language" class="language" lang="${lang==='en'?'es':'en'}">${lang==='en'?'Español':'English'}</button><button class="account-btn" data-action="help" aria-label="${c.help}">${glyph('user')}</button></div></header><div class="demo-ribbon"><span><i></i>${tx('INTERACTIVE DEMO','DEMO INTERACTIVA')}</span><p>${tx('No live alerts. No verified hosts. No requests sent.','Sin alertas en vivo, anfitriones verificados ni solicitudes enviadas.')}</p><button data-view="console">${glyph('console')}${tx('Coordinator view','Vista de coordinación')} ↗</button></div><div id="offline" class="offline" role="status" ${navigator.onLine?'hidden':''}>${c.offline}</div><main id="main" class="workspace" tabindex="-1">${({map:mapView,refuge:refugeView,alerts:alertsView,report:reportView,host:hostView,console:consoleView,care:careView})[currentView]()}</main><footer class="app-footer"><p>${tx('Built for community. Designed with care.','Para la comunidad. Diseñado con cuidado.')}</p><div><button data-action="status">${c.status}</button><button data-action="privacy">${c.privacy}</button><button id="reset-demo">${tx('Reset demo','Reiniciar demo')}</button></div></footer><nav class="mobile-nav" aria-label="${tx('Mobile navigation','Navegación móvil')}">${nav.map(([id,ic,label])=>`<button data-view="${id}" ${currentView===id?'aria-current="page"':''}>${glyph(ic)}<span>${label}</span></button>`).join('')}</nav></div>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>open(b.dataset.action));document.querySelector('#language').onclick=()=>{lang=lang==='en'?'es':'en';render();window.dispatchEvent(new CustomEvent('floodcare-language',{detail:lang}));document.querySelector('#language').focus()};document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{activeLayer=b.dataset.layer;render();document.querySelector(`[data-layer="${activeLayer}"]`).focus()});document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.service);document.querySelectorAll('[data-service]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#selection').textContent=c.chosen+' '+c.services[selected]});
 document.querySelector('[data-sim="refuge"]')?.addEventListener('click',()=>{selected=2;open('request')});document.querySelector('#report-add')?.addEventListener('click',()=>{reportAdded=true;render();document.querySelector('#view-title').focus()});document.querySelector('#host-available')?.addEventListener('change',e=>{hostAvailable=e.target.checked;render();document.querySelector('#host-available').focus()});document.querySelectorAll('[data-host]').forEach(b=>b.onclick=()=>{const choice=b.dataset.host;show(tx('Confirm a demo decision','Confirmar decisión demo'),`<p class="notice">${tx('This only records a fictional hosting decision in this page session. No guest will be contacted or sent to you.','Esto solo registra una decisión ficticia en esta sesión. No se contactará ni enviará a ningún huésped.')}</p><div class="actions"><button class="primary" id="host-confirm">${tx('Confirm demo decision','Confirmar decisión demo')}</button><button class="outline" data-close>${c.cancel}</button></div>`);document.querySelector('#host-confirm').onclick=()=>{hostChoice=choice;dialog.close();render();document.querySelector('#view-title').focus()}});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const id=b.dataset.review;show(tx('Review a fictional case','Revisar un caso ficticio'),`<p>${tx('A real coordinator would verify the source, contact appropriate services, and confirm any action. This demonstration cannot do those things.','Un coordinador real verificaría la fuente, contactaría a los servicios correspondientes y confirmaría cualquier acción. Esta demo no puede hacerlo.')}</p><p class="notice">${tx('Marking reviewed does not dispatch help or notify anyone.','Marcar como revisado no envía ayuda ni notifica a nadie.')}</p><button class="primary" id="review-confirm">${tx('Mark demo reviewed','Marcar demo revisada')}</button>`);document.querySelector('#review-confirm').onclick=()=>{reviewedCases.add(id);dialog.close();render();document.querySelector('#view-title').focus()}});
 document.querySelector('#reset-demo').onclick=()=>{show(tx('Reset this demo?','¿Reiniciar esta demo?'),`<p>${tx('Clear local hosting decisions, sample reports, and demo review status. The AI conversation is separate; use Clear chat to remove it.','Borra decisiones locales, reportes de ejemplo y revisiones demo. La conversación de IA es independiente; usa Borrar chat.')}</p><div class="actions"><button class="primary" id="reset-confirm">${tx('Reset demo','Reiniciar demo')}</button><button class="outline" data-close>${c.cancel}</button></div>`);document.querySelector('#reset-confirm').onclick=()=>{hostChoice='';hostAvailable=true;reportAdded=false;reviewedCases.clear();completed=false;selected=-1;activeLayer='all';dialog.close();go('map')}};
}
